using MunicipalPlatform.Api.Platform.Tenancy;
namespace MunicipalPlatform.Api.Modules.Operations.Domain;

public sealed class ChangelogEntry : ITenantEntity { private ChangelogEntry() { } public ChangelogEntry(Guid municipalityId, string title, string version, DateOnly releaseDate, string summary, string details, string impact, string audience) { Id = Guid.NewGuid(); MunicipalityId = municipalityId; Title = title.Trim(); Version = version.Trim(); ReleaseDate = releaseDate; Summary = summary.Trim(); Details = details; Impact = impact.Trim(); Audience = audience.Trim(); CreatedAt = DateTimeOffset.UtcNow; } public Guid Id { get; private set; } public Guid MunicipalityId { get; private set; } public string Title { get; private set; } = string.Empty; public string Version { get; private set; } = string.Empty; public DateOnly ReleaseDate { get; private set; } public string Summary { get; private set; } = string.Empty; public string Details { get; private set; } = string.Empty; public string Impact { get; private set; } = string.Empty; public string Audience { get; private set; } = string.Empty; public DateTimeOffset CreatedAt { get; private set; } }
